// App-specific typing glue. The Cloudflare primitives (KVNamespace, D1Database, WorkerLoader,
// SendEmail, etc.) come from apps/nuxflow/worker-configuration.d.ts, generated by
// `pnpm run cf-typegen` from wrangler.toml — re-run it after changing bindings. This file
// covers what that can't know: the bindings' optionality here, and the fields NuxFlow's own
// middleware puts on the H3 event context.
import type { Role } from '../utils/permissions'

export interface NuxFlowCloudflareEnv {
  PLUGIN_KV: KVNamespace
  LOADER: WorkerLoader
  DB?: D1Database
  AE?: AnalyticsEngineDataset
  EMAIL?: SendEmail
  /** Optional R2 bucket for the native media storage provider (server/utils/media-providers/r2.ts). */
  MEDIA_BUCKET?: R2Bucket
  /** Optional Workers AI binding — zero-config AI provider (server/utils/cf-env.ts's getWorkersAiBinding). */
  AI?: Ai
  /** Optional Vectorize index for semantic search / RAG embeddings (server/utils/cf-env.ts's getVectorizeIndex). */
  VECTORIZE?: VectorizeIndex
  [key: string]: unknown
}

declare global {
  /**
   * The Worker's env bindings, which Nitro puts here before running a scheduled task or
   * another non-request handler (no H3 event to carry them). Prefer the event's own
   * `context.cloudflare.env` whenever there is a request.
   */
  var __env__: NuxFlowCloudflareEnv | undefined
}

declare module 'h3' {
  interface H3EventContext {
    cloudflare?: {
      env: NuxFlowCloudflareEnv
      request: Request
      // Nitro's cloudflare-module preset (fetchHandler in nitropack's _module-handler)
      // exposes the Worker's ExecutionContext as `context` — there is no `ctx` key. Read
      // it through getExecutionContext() in server/utils/cf-env.ts rather than directly.
      context: { waitUntil(promise: Promise<unknown>): void }
    }

    // ── 02.multi-site.ts ──
    /** The site this request is for. Null on the accounts origin or an unknown host; unset on routes that skip site resolution. Read it with requireSiteId() unless a missing site is expected. */
    siteId?: string | null
    siteStatus?: 'active' | 'maintenance' | 'suspended' | null
    /** The site's main domain — differs from the request host on previews and extra domains. */
    siteDomain?: string | null
    setupCompleted?: boolean
    /** True on the central sign-in origin (NUXT_PUBLIC_ACCOUNTS_URL). */
    isAccountsHost?: boolean

    // ── 03.api-key-auth.ts — set only for a valid key whose owner still has a role on this site ──
    apiKeyUserId?: string
    apiKeyRole?: Role
    apiKeyScopes?: string[]

    /** 06.theme-preview.ts: an inactive theme an admin is previewing. */
    themePreviewId?: string
    /** 07.page-cache.ts: the site's cache version used for this request's page-cache key. */
    pageCacheVersion?: string
  }
}
